def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    mine = [h[0] for h in history]
    op_last = opp[-1]
    my_last = mine[-1]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a in mine if a == 'D')

    # Strong defectors: punish hard, with endgame exploitation.
    if opp_d * 10 >= n * 9:
        return 'D'
    if n >= 8 and opp_d * 4 >= n * 3:
        if op_last == 'D':
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'

    # Near endgame: exploit persistent cooperators.
    if n >= 88:
        if opp_d * 10 <= n:
            return 'D'
        if opp_d * 2 < n:
            return 'D' if rng.random() < 0.5 else 'C'

    # Probe trigger: if we've been badly exploited, secure points.
    if n >= 4 and my_d == 0 and opp_d * 3 >= n:
        return 'D'

    # Tit-for-tat-like core with forgiveness on isolated defections.
    if op_last == 'D':
        if opp_d <= 2 and n >= 6:
            return 'C' if rng.random() < 0.6 else 'D'
        if my_last == 'D' and opp_d * 2 <= n:
            return 'C'
        return 'D'

    # Opponent cooperated.
    # If we've been defecting a lot and they still cooperate, return to cooperation
    # to build score rather than continue exploiting a forgiving opponent.
    if my_last == 'D':
        if opp_d == 0:
            return 'C'
        if my_d > opp_d + 1:
            return 'C'

    # Exploit a fully cooperative opponent occasionally.
    if opp_d == 0 and n >= 10:
        if rng.random() < 0.18:
            return 'D'
        return 'C'

    # Mostly cooperate, small probing.
    if n >= 20 and opp_d * 5 <= n and rng.random() < 0.04:
        return 'D'
    return 'C'
